import{_ as i,c as l,o as a,a4 as e}from"./chunks/framework.CpVK_f0P.js";const m=JSON.parse('{"title":"工作场景练习","description":"","frontmatter":{},"headers":[],"relativePath":"practice/work-scenarios/index.md","filePath":"practice/work-scenarios/index.md"}'),t={name:"practice/work-scenarios/index.md"},r=e('<h1 id="工作场景练习" tabindex="-1">工作场景练习 <a class="header-anchor" href="#工作场景练习" aria-label="Permalink to &quot;工作场景练习&quot;">​</a></h1><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>用于记录真实或模拟的工作英语输出练习。先从<a href="./../../expressions/work-communication.html">工作交流语言块</a>选择 3～5 个表达，再把人物、项目、技术栈和问题替换成自己的真实情况。</p><h2 id="场景类型" tabindex="-1">场景类型 <a class="header-anchor" href="#场景类型" aria-label="Permalink to &quot;场景类型&quot;">​</a></h2><ul><li><strong>远程会议自救</strong>：没听清、请求重复、确认关键词、共享屏幕和网络问题</li><li><strong>每日站会</strong>：昨天完成了什么、今天计划做什么、有什么阻塞</li><li><strong>异步汇报与交接</strong>：跨时区更新进展、留下上下文、明确下一步负责人</li><li><strong>Bug 描述与排查</strong>：预期、实际结果、复现步骤、影响范围和原因猜测</li><li><strong>需求确认</strong>：用户目标、范围、验收标准、边界情况和截止时间</li><li><strong>技术解释</strong>：组件职责、请求链路、数据来源、技术选择和 trade-off</li><li><strong>代码评审</strong>：请求评审、解释修改、回应意见、确认是否可以合并</li><li><strong>发布与事故</strong>：部署状态、回滚、临时方案、监控和后续行动</li><li><strong>项目介绍与 Demo</strong>：项目目标、个人职责、挑战、行动、结果和功能演示</li><li><strong>个人介绍与问答</strong>：自我介绍、技术栈、项目经历、合作方式和工作安排</li></ul><h2 id="练习方式" tabindex="-1">练习方式 <a class="header-anchor" href="#练习方式" aria-label="Permalink to &quot;练习方式&quot;">​</a></h2><ol><li>选一个真实场景和 3～5 个目标语言块</li><li>只写关键词，不写完整逐字稿</li><li>脱稿说 60～90 秒</li><li>回听检查： <ul><li>卡顿是否超过 3 处？</li><li>是否说了完整句子？</li><li>是否有中式表达痕迹？</li><li>关键词发音有没有问题？</li><li>是否主动使用了目标语言块？</li><li>对方是否能明确知道下一步行动？</li></ul></li><li>让 AI 扮演同事、PM、客户或其他沟通对象，继续追问两个问题</li><li>纠正后再完整说一遍</li><li>第二天不看文本重新回答同一场景</li></ol><h2 id="每周轮换" tabindex="-1">每周轮换 <a class="header-anchor" href="#每周轮换" aria-label="Permalink to &quot;每周轮换&quot;">​</a></h2><ul><li>周一：会议自救</li><li>周二：Stand-up / 异步汇报</li><li>周三：Bug 描述与排查</li><li>周四：需求确认</li><li>周五：技术解释 / 代码评审</li><li>周六：项目介绍 / 技术问答 / Demo</li><li>周日：重新回答本周最卡的一次，或休息</li></ul><h2 id="练习记录" tabindex="-1">练习记录 <a class="header-anchor" href="#练习记录" aria-label="Permalink to &quot;练习记录&quot;">​</a></h2><p>（训练后在这里添加新的练习记录链接）</p>',11),o=[r];function n(s,c,h,d,u,_){return a(),l("div",null,o)}const p=i(t,[["render",n]]);export{m as __pageData,p as default};
